    12	type HTMLElementWithText = HTMLElement & RNText;
    13	
    14	function DisplayNamesWithToolTip({shouldUseFullTitle, fullTitle, displayNamesWithTooltips, textStyles = [], numberOfLines = 1, renderAdditionalText}: DisplayNamesProps) {
    15	    const styles = useThemeStyles();
    16	    const containerRef = useRef<HTMLElementWithText>(null);
    17	    const childRefs = useRef<HTMLElementWithText[]>([]);
    18	    const isEllipsisActive = !!containerRef.current?.offsetWidth && !!containerRef.current?.scrollWidth && containerRef.current.offsetWidth < containerRef.current.scrollWidth;
    19	
    20	    /**
    21	     * We may need to shift the Tooltip horizontally as some of the inline text wraps well with ellipsis,
    22	     * but their container node overflows the parent view which causes the tooltip to be misplaced.
    23	     *
    24	     * So we shift it by calculating it as follows:
    25	     * 1. We get the container layout and take the Child inline text node.
    26	     * 2. Now we get the tooltip original position.
    27	     * 3. If inline node's right edge is overflowing the container's right edge, we set the tooltip to the center
    28	     * of the distance between the left edge of the inline node and right edge of the container.
    29	     * @param index Used to get the Ref to the node at the current index
    30	     * @returns Distance to shift the tooltip horizontally
    31	     */
    32	    const getTooltipShiftX = useCallback((index: number) => {
    33	        // Only shift the tooltip in case the containerLayout or Refs to the text node are available
    34	        if (!containerRef.current || !childRefs.current[index]) {
    35	            return 0;
    36	        }
    37	        const {width: containerWidth, left: containerLeft} = containerRef.current.getBoundingClientRect();
    38	
    39	        // We have to return the value as Number so we can't use `measureWindow` which takes a callback
    40	        const {width: textNodeWidth, left: textNodeLeft} = childRefs.current[index].getBoundingClientRect();
    41	        const tooltipX = textNodeWidth / 2 + textNodeLeft;
    42	        const containerRight = containerWidth + containerLeft;
    43	        const textNodeRight = textNodeWidth + textNodeLeft;
    44	        const newToolX = textNodeLeft + (containerRight - textNodeLeft) / 2;
    45	
    46	        // When text right end is beyond the Container right end
    47	        return textNodeRight > containerRight ? -(tooltipX - newToolX) : 0;
    48	    }, []);
    49	
    50	    return (
    51	        // Tokenization of string only support prop numberOfLines on Web
    52	        <Text
    53	            style={[textStyles, styles.pRelative]}
    54	            numberOfLines={numberOfLines || undefined}
    55	            ref={containerRef}
    56	            testID={DisplayNamesWithToolTip.displayName}
    57	        >
    58	            {shouldUseFullTitle
    59	                ? ReportUtils.formatReportLastMessageText(fullTitle)
    60	                : displayNamesWithTooltips?.map(({displayName, accountID, avatar, login}, index) => (
    61	                      // eslint-disable-next-line react/no-array-index-key
    62	                      <Fragment key={index}>
    63	                          <DisplayNamesTooltipItem
    64	                              index={index}
    65	                              getTooltipShiftX={getTooltipShiftX}
    66	                              accountID={accountID}
    67	                              displayName={displayName}
    68	                              login={login}
    69	                              avatar={avatar}
    70	                              textStyles={textStyles}
    71	                              childRefs={childRefs}
    72	                          />
    73	                          {index < displayNamesWithTooltips.length - 1 && <Text style={textStyles}>,&nbsp;</Text>}
    74	                      </Fragment>
    75	                  ))}
    76	            {renderAdditionalText?.()}
    77	            {!!isEllipsisActive && (
    78	                <View style={styles.displayNameTooltipEllipsis}>
    79	                    <Tooltip text={fullTitle}>
    80	                        {/* There is some Gap for real ellipsis so we are adding 4 `.` to cover */}
    81	                        <Text>....</Text>
    82	                    </Tooltip>
    83	                </View>
    84	            )}
    85	        </Text>
    86	    );
    87	}
